import React, { useMemo } from "react";
import { useNavigate } from "react-router-dom";
import "./style/Comparison.css";

function Comparison() {
  const navigate = useNavigate();

  const saved = useMemo(() => {
    try {
      return JSON.parse(localStorage.getItem("fs_results")) || null;
    } catch {
      return null;
    }
  }, []);

  const d = saved?.data || {};

  // نبني صفوف حسب الموجود
  const rows = [
    d.genetic_accuracy ?? d.ga_accuracy ?? d.accuracy
      ? { method: "الخوارزمية الجينية", key: "ga", acc: d.genetic_accuracy ?? d.ga_accuracy ?? d.accuracy, color: "#be185d" }
      : null,
    d.mutual_info_accuracy ?? d.mi_accuracy
      ? { method: "Mutual Information", key: "mi", acc: d.mutual_info_accuracy ?? d.mi_accuracy, color: "#ec4899" }
      : null,
    d.pca_accuracy
      ? { method: "PCA", key: "pca", acc: d.pca_accuracy, color: "#f472b6" }
      : null,
    d.rfe_accuracy
      ? { method: "RFE (Logistic Regression)", key: "rfe", acc: d.rfe_accuracy, color: "#f472b6" }
      : null,
    d.chi_accuracy
      ? { method: "Chi-Square", key: "chi", acc: d.chi_accuracy, color: "#f472b6" }
      : null,
  ].filter(Boolean);

  // fallback إذا ما فيه داتا
  const data = rows.length
    ? rows.map(r => ({
        method: r.method,
        accuracy: `${(r.acc * (r.acc <= 1 ? 100 : 1)).toFixed(2)}%`,
        color: r.color
      }))
    : [
        { method: "الخوارزمية الجينية", accuracy: "94%", color: "#be185d" },
        { method: "Mutual Information", accuracy: "91%", color: "#ec4899" },
        { method: "PCA", accuracy: "89%", color: "#f472b6" },
        { method: "RFE (Logistic Regression)", accuracy: "89%", color: "#f472b6" },
        { method: "Chi-Square", accuracy: "89%", color: "#f472b6" },
      ];

  return (
    <div className="comparison-container">
      <h1 className="comparison-title">مقارنة بين طرق اختيار الخصائص</h1>

      <p className="comparison-description">
        الجدول يعرض دقة النماذج حسب الخوارزميات المتاحة من الخادم. إذا لم تكن هناك نتائج حديثة،
        يتم عرض قيم افتراضية لتوضيح الشكل العام.
      </p>

      <table className="comparison-table">
        <thead>
          <tr>
            <th>الطريقة</th>
            <th>دقة النموذج</th>
          </tr>
        </thead>
        <tbody>
          {data.map((row, idx) => (
            <tr key={idx}>
              <td style={{ color: row.color, fontWeight: "bold" }}>{row.method}</td>
              <td>{row.accuracy}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <button onClick={() => navigate("/results")} className="comparison-btn">
        العودة إلى النتائج
      </button>
    </div>
  );
}

export default Comparison;
